import { describe, it, expect } from 'vitest';
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { importMostab } from './index';
import { lookup } from '../lookup';

// Generated by `uv run --with numpy python3 tools/test_medwatt2mostab.py` from a
// synthetic mosplot .npz — proves the Python converter emits valid mostab that the
// core importer round-trips into a correct N-D grid.
const csv = readFileSync(
  fileURLToPath(new URL('../../tools/__fixtures__/medwatt_demo.mostab.csv', import.meta.url)),
  'utf8',
);

describe('medwatt2mostab → importMostab round-trip', () => {
  it('imports the converter output into a complete [l × vsb × vgs × vds] grid', () => {
    const r = importMostab(csv, { filename: 'medwatt_demo.csv' });
    expect(r.ok).toBe(true);
    if (!r.ok) return;

    const t = r.dataset.tables[0];
    expect(t.id.device).toBe('medwatt_demo');
    expect(t.grid.axes.map((a) => a.name).sort()).toEqual(['l', 'vds', 'vgs', 'vsb']);
    expect(t.grid.shape.reduce((a, b) => a * b, 1)).toBe(24); // 2×2×3×2

    // vsb carries the sign-flipped values {0, 0.3} (vbs was {0, -0.3}).
    const vsb = t.grid.axes.find((a) => a.name === 'vsb')!;
    expect(Array.from(vsb.values)).toEqual([0, 0.3]);

    // gm/ID = 10 everywhere in the synthetic table; id is exact at a node.
    const q = lookup(t, { l: 100e-9, vds: 1.0, vgs: 0.7, vsb: 0 }, ['gm_id', 'id']);
    expect(q.gm_id).toBeCloseTo(10, 9);
    expect(q.id).toBeCloseTo(6e-6, 18);
  });
});
